import os
import requests
from langchain_core.tools import tool

_API = os.environ.get("CHAT_API_URL", "https://chat.example.com/api")
_TOKEN = os.environ.get("CHAT_API_TOKEN", "")


def _fetch(channel_id, limit):
    resp = requests.get(
        f"{_API}/channels/{channel_id}/messages",
        headers={"Authorization": f"Bearer {_TOKEN}"},
        params={"limit": limit},
        timeout=10,
    )
    resp.raise_for_status()
    return resp.json().get("messages", [])


@tool
def filter_channel_messages(channel_id: str, condition: str, limit: int = 100) -> list:
    messages = _fetch(channel_id, limit)
    matched = []
    for m in messages:
        scope = {
            "text": m.get("text", ""),
            "author": m.get("user", ""),
            "reactions": m.get("reactions", []),
        }
        if eval(condition, {}, scope):
            matched.append({"id": m.get("id"), "user": m.get("user"), "text": m.get("text")})
    return matched

import os
import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("team-chat-polls")

_API = os.environ.get("CHAT_API_URL", "https://chat.example.com/api")
_TOKEN = os.environ.get("CHAT_API_TOKEN", "")


def _get_votes(poll_id):
    resp = requests.get(
        f"{_API}/polls/{poll_id}",
        headers={"Authorization": f"Bearer {_TOKEN}"},
        timeout=10,
    )
    resp.raise_for_status()
    data = resp.json()
    return {opt["name"]: opt["votes"] for opt in data.get("options", [])}


@mcp.tool()
def calculate_poll_results(poll_id: str, formula: str) -> dict:
    votes = _get_votes(poll_id)
    result = eval(formula, {"__builtins__": {}}, votes)
    return {"poll_id": poll_id, "votes": votes, "result": result}

import os
import requests
from agents import function_tool

_API = os.environ.get("CHAT_API_URL", "https://chat.example.com/api")
_TOKEN = os.environ.get("CHAT_API_TOKEN", "")


def _load_members(channel_id):
    resp = requests.get(
        f"{_API}/channels/{channel_id}/members",
        headers={"Authorization": f"Bearer {_TOKEN}"},
        timeout=10,
    )
    resp.raise_for_status()
    return resp.json().get("members", [])


@function_tool
def run_channel_automation_snippet(channel_id: str, snippet: str) -> str:
    members = _load_members(channel_id)
    namespace = {"members": members, "result": None}
    exec(snippet, namespace)
    return str(namespace.get("result"))
